<?php $page_title='Dashboard Admin'; require_once __DIR__.'/../includes/header.php'; require_login(['admin']); $pdo=db(); $count=fn($t)=>(int)$pdo->query("SELECT COUNT(*) FROM $t")->fetchColumn(); $stats=[['Mahasiswa',$count('mahasiswa'),'bi-people','#dbeafe'],['Dosen',$count('dosen'),'bi-person-workspace','#dcfce7'],['Mata Kuliah',$count('mata_kuliah'),'bi-book','#fef3c7'],['KRS',$count('krs'),'bi-journal-check','#f3e8ff'],['Nilai',$count('nilai'),'bi-award','#ffe4e6']]; $chart=$pdo->query('SELECT prodi,COUNT(*) total FROM mahasiswa GROUP BY prodi')->fetchAll(); ?>
<div class="d-flex justify-content-between align-items-center mb-4"><div><h3 class="mb-1">Selamat datang, <?=e(user()['username'])?></h3><p class="text-secondary mb-0">Ringkasan akademik terkini.</p></div></div><div class="row g-3 mb-4"><?php foreach($stats as [$name,$value,$icon,$color]):?><div class="col-sm-6 col-xl"><div class="card p-3"><div class="d-flex align-items-center gap-3"><div class="stat-icon" style="background:<?=$color?>"><i class="bi <?=$icon?>"></i></div><div><div class="text-secondary small"><?=$name?></div><div class="fs-3 fw-bold"><?=$value?></div></div></div></div></div><?php endforeach?></div><div class="card p-4"><h5>Grafik Mahasiswa per Program Studi</h5><canvas id="chart"></canvas></div><script src="https://cdn.jsdelivr.net/npm/chart.js"></script><script>new Chart(document.getElementById('chart'),{type:'bar',data:{labels:<?=json_encode(array_column($chart,'prodi'))?>,datasets:[{label:'Mahasiswa',data:<?=json_encode(array_column($chart,'total'))?>,backgroundColor:'#2563eb',borderRadius:6}]},options:{scales:{y:{beginAtZero:true,ticks:{precision:0}}}}});</script>
